-- Bolton Vouched: New trades and renames of 26 October (air conditioning to cupping and hijama) for the LIVE Supabase project
-- (mmarznvndvbwyhhtbfjy).
-- Paste ALL of this into Supabase -> SQL Editor -> New query -> Run, once. It is one transaction: if anything
-- fails, nothing is changed. Confirm the 'destructive operation' warning (it comes from 'create or replace' and
-- 'drop ... if exists' lines; no data is deleted). The checks at the end fail the whole paste if a piece is missing.
-- Generated by scripts/build-production-sql.mjs from supabase/migrations/20261012000046_air_conditioning.sql .. 20261012000051_cupping_hijama.sql;
-- do not edit by hand.
begin;

-- Run the builders script (docs/launch/builders-production.sql) first: this stops (changing nothing) if it hasn't been.
do $requires$
begin
  if not exists (select 1 from supabase_migrations.schema_migrations where version = '20261012000045') then
    raise exception 'Run the builders script (docs/launch/builders-production.sql) first: migration 20261012000045 is not recorded';
  end if;
end
$requires$;

-- ==== 20261012000046_air_conditioning.sql
-- Air conditioning, requested by the owner. Home & trades, with the check that matters: by law only F-gas certified
-- engineers can install it.
-- Idempotent: safe to run again.
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, 'air-conditioning', 'Air conditioning', 'none'::public.category_requirement,
  'Air conditioning must be installed by an F-gas certified engineer: ask to see their certificate. Ask where the outdoor unit will go and how loud it is, and get the unit model, the price and the warranty in writing.'
from public.category_groups g where g.slug = 'home-trades'
on conflict (slug) do nothing;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000046', 'air_conditioning') on conflict do nothing;

-- ==== 20261012000047_personal_trainers.sql
-- Personal trainers, requested by the owner. The trade already existed as "Fitness", which a personal trainer looking
-- down the list could miss: renamed so they find it, with a tip for customers.
-- Idempotent: safe to run again.
update public.categories
set name = 'Personal trainers & fitness',
    guidance_note = 'Ask about their qualification (a Level 3 personal training certificate is the usual standard) and their insurance, and tell them about any injuries or health conditions before the first session.'
where slug = 'fitness';

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000047', 'personal_trainers') on conflict do nothing;

-- ==== 20261012000048_weddings_and_events.sql
-- Wedding vendors, requested by the owner: the people who do stages, canapés and dessert tables, and who hire things
-- out for functions. The group is renamed "Weddings & events", its trades say what they cover (Catering & canapés,
-- Cakes & desserts, Stages & decor), each with a tip for customers, and there's a new trade for hire firms
-- (marquees, furniture, dance floors, photo booths). Slugs stay the same, so links and listings don't change.
-- Idempotent: safe to run again.
update public.category_groups set name = 'Weddings & events' where slug = 'events-occasions';
update public.categories set name = 'Catering & canapés', guidance_note = 'Ask for their food hygiene rating (it''s on the Food Standards Agency website) and tell them about any allergies. Get the menu, numbers and price per head in writing.' where slug = 'caterer';
update public.categories set name = 'Cakes & desserts', guidance_note = 'Ask for their food hygiene rating (it''s on the Food Standards Agency website) and tell them about any allergies. Agree the design, delivery time and deposit in writing.' where slug = 'cakes';
update public.categories set name = 'Stages & decor', guidance_note = 'Agree in writing what''s included, when they set up and clear away, and the deposit. Check the venue allows outside decorators.' where slug = 'decor';
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, 'event-hire', 'Event hire', 'none'::public.category_requirement, 'Agree in writing what''s included, the delivery and collection times, the deposit, and who pays for any damage. Check the venue allows it.'
from public.category_groups g where g.slug = 'events-occasions'
on conflict (slug) do nothing;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000048', 'weddings_and_events') on conflict do nothing;

-- ==== 20261012000049_building_surveyors.sql
-- Building surveyors, requested by the owner: house surveys before buying, party wall awards, and defect reports for
-- extensions. Home & trades, next to Builders, with the check that matters (RICS) and what to agree in writing.
-- Idempotent: safe to run again.
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, 'building-surveyors', 'Building surveyors', 'none'::public.category_requirement,
  'Ask if they''re RICS registered (you can check on the RICS website). Agree in writing which survey you''re getting (a Level 2 or Level 3 survey, a party wall award or a defects report), the fee and when you''ll have the report.'
from public.category_groups g where g.slug = 'home-trades'
on conflict (slug) do nothing;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000049', 'building_surveyors') on conflict do nothing;

-- ==== 20261012000050_more_trades.sql
-- Trades the outreach list and common Bolton jobs showed were missing, agreed with the owner: fencing, decking and
-- landscaping; damp proofing and insulation; tree surgeons. Man & van also covers full house removals now (renamed,
-- same slug, so links and listings don't change). Each with a tip for customers.
-- Idempotent: safe to run again.
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, v.slug, v.name, 'none'::public.category_requirement, v.note
from public.category_groups g
cross join (values
  ('fencing-landscaping', 'Fencing, decking & landscaping', 'Agree in writing what''s included (posts, panels, concrete, taking the old fence away), the price and the start date. For a boundary fence, talk to your neighbour first.'),
  ('damp-insulation', 'Damp proofing & insulation', 'Ask what''s causing the damp before agreeing to treatment: a lot of damp is condensation or a leak, not rising damp. Get the work, the price and any guarantee in writing.'),
  ('tree-surgeons', 'Tree surgeons', 'Ask for their public liability insurance and their tree work qualifications (NPTC certificates). If the tree has a Tree Preservation Order or is in a conservation area, you need the council''s permission first.')
) as v(slug, name, note)
where g.slug = 'home-trades'
on conflict (slug) do nothing;
update public.categories set name = 'Man & van, removals', guidance_note = 'For a full house move, ask if they have goods in transit insurance, and agree the price, the date and what''s included (packing, dismantling furniture) in writing.' where slug = 'man-and-van';

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000050', 'more_trades') on conflict do nothing;

-- ==== 20261012000051_cupping_hijama.sql
-- Cupping and hijama, requested by the owner. Personal & lessons, with the checks that matter for a treatment that
-- breaks the skin: council skin-piercing registration, single-use equipment, and telling them about medical conditions.
-- Idempotent: safe to run again.
insert into public.categories (group_id, slug, name, requirement, guidance_note)
select g.id, 'cupping-hijama', 'Cupping & hijama', 'none'::public.category_requirement,
  'Wet cupping (hijama) breaks the skin. Ask if they''re registered with the council for skin piercing, and check they use new single-use blades and cups for every client. Tell them about any medical conditions or blood-thinning medicines first.'
from public.category_groups g where g.slug = 'personal-lessons'
on conflict (slug) do nothing;

insert into supabase_migrations.schema_migrations (version, name) values ('20261012000051', 'cupping_hijama') on conflict do nothing;

-- ==================================================================== verification
-- Fails (and so rolls back everything above) if any piece is missing.
do $verify$
begin
  if not exists (select 1 from public.categories c join public.category_groups g on g.id = c.group_id
                 where c.active and c.slug = 'air-conditioning' and g.slug = 'home-trades') then
    raise exception 'Air conditioning check failed: the Air conditioning trade is missing';
  end if;
  if not exists (select 1 from public.categories where active and slug = 'fitness' and name = 'Personal trainers & fitness') then
    raise exception 'Air conditioning check failed: Fitness is not renamed to Personal trainers & fitness';
  end if;
  if not exists (select 1 from public.categories c join public.category_groups g on g.id = c.group_id
                 where c.active and c.slug = 'event-hire' and g.slug = 'events-occasions' and g.name = 'Weddings & events')
     or (select count(*) from public.categories
         where slug in ('caterer', 'cakes', 'decor') and name in ('Catering & canapés', 'Cakes & desserts', 'Stages & decor')) <> 3 then
    raise exception 'Air conditioning check failed: the weddings and events changes are missing';
  end if;
  if not exists (select 1 from public.categories c join public.category_groups g on g.id = c.group_id
                 where c.active and c.slug = 'building-surveyors' and g.slug = 'home-trades') then
    raise exception 'Air conditioning check failed: the Building surveyors trade is missing';
  end if;
  if (select count(*) from public.categories c join public.category_groups g on g.id = c.group_id
      where c.active and g.slug = 'home-trades'
        and c.slug in ('fencing-landscaping', 'damp-insulation', 'tree-surgeons')) <> 3
     or not exists (select 1 from public.categories where slug = 'man-and-van' and name = 'Man & van, removals') then
    raise exception 'Air conditioning check failed: the fencing, damp, tree surgeon or removals changes are missing';
  end if;
  if not exists (select 1 from public.categories c join public.category_groups g on g.id = c.group_id
                 where c.active and c.slug = 'cupping-hijama' and g.slug = 'personal-lessons') then
    raise exception 'Air conditioning check failed: the Cupping & hijama trade is missing';
  end if;
end
$verify$;

commit;

select 'Air conditioning applied' as result,
       (select count(*) from supabase_migrations.schema_migrations where version in ('20261012000046', '20261012000047', '20261012000048', '20261012000049', '20261012000050', '20261012000051')) as migrations_recorded;
